import Foundation

/// The built-in outfit recipes: classic, brand-free menswear formulas for every style and season
/// (`recipes.json`, generated by `tools/knowledge/style_library.py`).
public enum RecipeLibrary {
    public static let standard: [StyleRecipe] = loadResource("recipes", as: [StyleRecipe].self) ?? []
}

/// One piece of the generic capsule closet: a plain, unbranded basic ("white oxford shirt").
public struct CapsuleItem: Sendable, Hashable, Codable, Identifiable {
    public var id: String
    public var name: String
    public var category: GarmentCategory
    public var subcategory: String
    public var color: String
    public var secondaryColor: String?
    public var pattern: Pattern
    public var material: String
    public var formality: Int
    public var seasons: [Season]
    /// Plain description used to draw the product photo.
    public var description: String
}

/// A balanced closet of basics that can wear every library recipe (`capsule.json`).
public enum GenericCapsule {
    public static let items: [CapsuleItem] = loadResource("capsule", as: [CapsuleItem].self) ?? []
}

func loadResource<T: Decodable>(_ name: String, as type: T.Type) -> T? {
    guard let url = Bundle.module.url(forResource: name, withExtension: "json"),
          let data = try? Data(contentsOf: url)
    else { return nil }
    return try? JSONDecoder().decode(T.self, from: data)
}
